    "privacyUseNotifications" to "Vous envoyer des notifications importantes concernant votre compte et la sécurité",
    "privacyOnceConnected" to "Une fois que vous êtes en contact avec un autre utilisateur via notre plateforme, toute communication ultérieure se déroule directement entre vous et cette personne. Nous ne surveillons pas, ne stockons pas et n'avons pas accès au contenu de vos communications.",
    "privacyNeverDoH3" to "Ce que nous ne ferons jamais",
    "privacyCommitIntro" to "Nous nous engageons solennellement à :",
    "privacyNoAdsLabel" to "Pas de publicité : ",
    "privacyNoAdsDesc" to "Nous n'afficherons jamais de publicités ciblées ou non ciblées basées sur votre activité",
    "privacyNoMarketingLabel" to "Pas de marketing : ",
    "privacyNoMarketingDesc" to "Nous ne partagerons jamais votre e-mail avec des tiers à des fins de marketing ou promotionnelles",
    "privacyNoSellingLabel" to "Pas de vente de données : ",
    "privacyNoSellingDesc" to "Nous ne vendrons, ne louerons ni ne transférerons jamais vos informations personnelles à un tiers",
    "privacyNoProfilingLabel" to "Pas de profilage : ",
    "privacyNoProfilingDesc" to "Nous n'utiliserons pas vos données pour créer des profils à d'autres fins que la gestion de base du compte",
    "privacyNoTrackingLabel" to "Pas de suivi : ",
    "privacyNoTrackingDesc" to "Nous n'utilisons pas de pixels de suivi, de cookies publicitaires ni de technologies de suivi similaires",
    "privacyDataStorageH2" to "Stockage et sécurité des données",
    "privacyDataStoredSecurely" to "Vos données sont stockées en toute sécurité grâce à un chiffrement conforme aux normes du secteur. Nous mettons en œuvre des mesures techniques et organisationnelles appropriées pour protéger vos informations personnelles contre tout accès, modification, divulgation ou destruction non autorisés.",
    "privacyDataRetention" to "Nous conservons les informations de votre compte tant que celui-ci reste actif. Vous pouvez demander la suppression de votre compte et des données associées à tout moment en nous contactant.",
    "privacyYourRightsH2" to "Vos droits",
    "privacyRightsIntro" to "Vous disposez des droits suivants concernant vos données personnelles :",
    "privacyRightAccess" to "Accès : Vous pouvez demander une copie de toutes les données personnelles que nous détenons à votre sujet",
    "privacyRightCorrection" to "Rectification : Vous pouvez demander que nous corrigions toute information inexacte",
    "privacyRightDeletion" to "Suppression : Vous pouvez demander que nous supprimions votre compte et toutes les données associées",
    "privacyRightPortability" to "Portabilité : Vous pouvez demander que nous vous fournissions vos données dans un format couramment utilisé",
    "privacyExerciseRights" to "Pour exercer l'un de ces droits, veuillez nous contacter à admin@adopt-u.com.",
    "privacyCookiesH2" to "Cookies",
    "privacyCookiesText" to "Adopt-U utilise le minimum de cookies nécessaires au fonctionnement de la plateforme, notamment la gestion des sessions et les préférences linguistiques. Nous n'utilisons pas de cookies publicitaires ou de suivi.",
    "privacyThirdPartyH2" to "Services tiers",
    "privacyThirdPartyIntro" to "Nous utilisons les services tiers suivants, qui peuvent traiter vos données :",
    "privacyAws" to "AWS (Amazon Web Services) : Pour le stockage des données et l'envoi d'e-mails. Leurs politiques de confidentialité s'appliquent au traitement de vos données.",
    "privacyWebauthn" to "WebAuthn/FIDO2 : Pour l'authentification sécurisée par passkey. Cela implique des opérations cryptographiques dans votre navigateur.",
    "privacyThirdPartySelected" to "Nous avons soigneusement sélectionné des prestataires de services qui partagent notre engagement envers la confidentialité des données.",
    "privacyChildrensH2" to "Confidentialité des mineurs",
    "privacyChildrensText" to "Adopt-U n'est pas destiné aux utilisateurs de moins de 18 ans. Nous ne collectons pas sciemment d'informations auprès de mineurs. Si vous pensez qu'un mineur a créé un compte, veuillez nous contacter pour le faire supprimer.",
    "privacyChangesH2" to "Modifications de cette politique",
    "privacyChangesText" to "Nous pouvons mettre à jour cette politique de confidentialité de temps à autre pour refléter des changements dans nos pratiques ou des exigences légales. Nous informerons les utilisateurs des changements importants par e-mail ou par un avis bien visible sur la plateforme.",
    "privacyContactH2" to "Nous contacter",
    "privacyContactText" to "Si vous avez des questions ou des préoccupations concernant cette politique de confidentialité, ou pour exercer vos droits sur vos données, veuillez nous contacter à admin@adopt-u.com.",
    "termsConditions" to "Conditions générales",
    "termsAcceptanceH2" to "Acceptation des conditions",
    "termsAcceptanceText" to "En accédant à Adopt-U et en l'utilisant, vous acceptez d'être lié par les termes et dispositions de cet accord. Si vous n'acceptez pas ces conditions, veuillez ne pas utiliser notre plateforme.",
    "termsNatureH2" to "Nature de notre service",
    "termsNatureText1" to "Adopt-U est une plateforme de mise en relation qui facilite le contact entre sauveteurs d'animaux et adoptants potentiels. Nous ne sommes ni une animalerie, ni un courtier, ni un refuge, ni une agence d'adoption. Nous ne possédons, ne gardons ni ne gérons directement aucun animal répertorié sur notre plateforme.",
    "termsNatureText2" to "Notre rôle se limite strictement à fournir un canal de communication entre les parties. Nous ne participons pas aux négociations d'adoption, aux contrats ni au transfert physique des animaux.",
    "termsUserRespH2" to "Responsabilités de l'utilisateur",
    "termsForRescuersH3" to "Pour les Sauveteurs :",
    "termsRescuerResp1" to "Fournir des informations exactes et véridiques sur les animaux dont vous avez la charge",
    "termsRescuerResp2" to "S'assurer que les animaux sont en bonne santé, vaccinés et correctement examinés avant leur publication",
    "termsRescuerResp3" to "Effectuer une sélection responsable des adoptants potentiels",
    "termsRescuerResp4" to "Organiser un transfert sécurisé des animaux vers leur nouveau foyer",
    "termsRescuerResp5" to "Accepter la responsabilité de l'exactitude de toutes les informations fournies",
    "termsRescuerResp6" to "Se conformer à toutes les lois et réglementations locales relatives à l'adoption d'animaux",
    "termsRescuerResp7" to "Ne jamais utiliser la plateforme à des fins de vente commerciale d'animaux ou d'élevage",
    "termsForAdoptersH3" to "Pour les Adoptants :",
    "termsAdopterResp1" to "Fournir des informations exactes sur votre situation de logement et votre expérience avec les animaux",
    "termsAdopterResp2" to "Être prêt à démontrer votre capacité à offrir des soins appropriés",
    "termsAdopterResp3" to "Comprendre que l'annulation de l'adoption d'un animal lui cause un stress important",
    "termsAdopterResp4" to "Respecter le droit du sauveteur de refuser votre demande d'adoption",
    "termsPetListingsH2" to "Annonces et informations sur les animaux",
    "termsPetListingsText1" to "Adopt-U ne vérifie, n'approuve ni ne garantit l'exactitude des informations fournies dans les annonces d'animaux. Les informations, y compris mais sans s'y limiter la race, l'âge, l'état de santé, le tempérament et les registres de vaccination, sont fournies par les sauveteurs et n'ont pas été vérifiées de manière indépendante.",
    "termsPetListingsText2" to "Les photos et descriptions sont fournies par les sauveteurs. Bien que nous interdisions toute fausse déclaration délibérée, nous ne pouvons garantir que toutes les annonces représentent fidèlement l'état actuel de l'animal.",
    "termsPetListingsText3" to "Les utilisateurs sont encouragés à poser des questions, demander les dossiers vétérinaires et rencontrer les animaux avant de finaliser tout arrangement d'adoption.",
    "termsAdoptionProcessH2" to "Processus d'adoption",
    "termsAdoptionProcessIntro" to "Une fois qu'un sauveteur et un adoptant conviennent de procéder à une adoption :",
    "termsAdoptionStep1" to "Tous les arrangements, y compris la date de transfert, le lieu et les coûts associés, sont négociés directement entre les parties",
    "termsAdoptionStep2" to "Adopt-U ne facilite ni ne garantit aucune transaction de paiement",
    "termsAdoptionStep3" to "La plateforme ne fournit pas de contrats d'adoption ; tout arrangement contractuel relève de la seule responsabilité des parties concernées",
    "termsAdoptionStep4" to "Nous recommandons vivement de documenter tous les accords par écrit",
    "termsLiabilityH2" to "Limitation de responsabilité",
    "termsLiabilityIntro" to "Adopt-U ne pourra être tenu responsable de :",
    "termsLiability1" to "Tout litige, désaccord ou conflit entre sauveteurs et adoptants",
    "termsLiability2" to "L'exactitude des informations fournies dans les annonces d'animaux",
    "termsLiability3" to "L'état de santé, le comportement ou la condition de tout animal avant, pendant ou après l'adoption",
    "termsLiability4" to "Toute perte financière, tout dommage ou toute blessure résultant de l'utilisation de la plateforme",
    "termsLiability5" to "Le résultat de toute adoption, y compris mais sans s'y limiter les retours, problèmes de santé ou de compatibilité",
    "termsLiability6" to "Toute action entreprise par les utilisateurs en dehors de la plateforme après l'établissement du contact",
    "termsLiabilityAck" to "Les utilisateurs reconnaissent que l'adoption d'un animal est un engagement important et qu'ils assument l'entière responsabilité de leur décision d'adopter.",
    "termsProhibitedH2" to "Activités interdites",
    "termsProhibitedIntro" to "Les activités suivantes sont strictement interdites sur Adopt-U :",
    "termsProhibited1" to "Vente commerciale d'animaux, opérations d'élevage ou élevages intensifs",
    "termsProhibited2" to "Publier des annonces pour des animaux dont vous n'avez pas directement la charge",
    "termsProhibited3" to "Informations fausses ou trompeuses dans les annonces ou les profils",
    "termsProhibited4" to "Harcèlement, discrimination ou contact inapproprié avec d'autres utilisateurs",
    "termsProhibited5" to "Utiliser la plateforme pour collecter des informations personnelles à des fins sans rapport avec l'adoption d'animaux",
    "termsProhibited6" to "Toute activité illégale ou violation des lois sur le bien-être animal",
    "termsAccountTerminationH2" to "Résiliation de compte",
    "termsAccountTerminationText" to "Adopt-U se réserve le droit de suspendre ou de résilier les comptes qui violent ces conditions, se livrent à des activités interdites ou nuisent à la réputation de la plateforme. Nous pouvons également supprimer les annonces contenant du contenu faux, trompeur ou inapproprié.",
    "termsModificationsH2" to "Modifications des conditions",
    "termsModificationsText" to "Nous nous réservons le droit de modifier ces conditions à tout moment. La poursuite de l'utilisation de la plateforme après les modifications constitue une acceptation des conditions modifiées. Nous informerons les utilisateurs des changements importants par e-mail ou par des annonces sur la plateforme.",
    "termsContactText" to "Si vous avez des questions concernant ces conditions générales, veuillez nous contacter à admin@adopt-u.com.",
