    "privacyCookiesText" to "Adopt-U использует минимальное количество файлов cookie, необходимых для работы платформы, включая управление сеансами и языковые предпочтения. Мы не используем рекламные или отслеживающие файлы cookie.",
    "privacyThirdPartyH2" to "Сторонние сервисы",
    "privacyThirdPartyIntro" to "Мы используем следующие сторонние сервисы, которые могут обрабатывать ваши данные:",
    "privacyAws" to "AWS (Amazon Web Services): для хранения данных и доставки электронной почты. К обработке ваших данных применяется их политика конфиденциальности.",
    "privacyWebauthn" to "WebAuthn/FIDO2: для безопасной аутентификации с помощью passkey. Включает криптографические операции в вашем браузере.",
    "privacyThirdPartySelected" to "Мы тщательно отобрали поставщиков услуг, разделяющих нашу приверженность конфиденциальности данных.",
    "privacyChildrensH2" to "Конфиденциальность детей",
    "privacyChildrensText" to "Adopt-U не предназначен для пользователей младше 18 лет. Мы сознательно не собираем информацию от несовершеннолетних. Если вы считаете, что несовершеннолетний создал аккаунт, свяжитесь с нами, чтобы удалить его.",
    "privacyChangesH2" to "Изменения в настоящей политике",
    "privacyChangesText" to "Мы можем время от времени обновлять настоящую Политику конфиденциальности, чтобы отразить изменения в нашей практике или требованиях законодательства. Мы будем уведомлять пользователей о существенных изменениях по электронной почте или с помощью заметного уведомления на платформе.",
    "privacyContactH2" to "Связаться с нами",
    "privacyContactText" to "Если у вас есть вопросы или замечания относительно настоящей Политики конфиденциальности, а также для реализации ваших прав на данные, свяжитесь с нами по адресу admin@adopt-u.com.",
    "termsConditions" to "Условия использования",
    "termsAcceptanceH2" to "Принятие условий",
    "termsAcceptanceText" to "Получая доступ к Adopt-U и используя платформу, вы принимаете условия и положения настоящего соглашения и соглашаетесь их соблюдать. Если вы не согласны с этими условиями, пожалуйста, не используйте нашу платформу.",
    "termsNatureH2" to "Характер нашего сервиса",
    "termsNatureText1" to "Adopt-U — это платформа для установления контактов, которая облегчает связь между спасателями животных и потенциальными усыновителями. Мы не являемся зоомагазином, посредником, приютом или агентством по усыновлению. Мы не владеем животными, размещёнными на нашей платформе, не осуществляем над ними опеку и не выступаем посредником в их передаче.",
    "termsNatureText2" to "Наша роль строго ограничена предоставлением канала связи между сторонами. Мы не участвуем в переговорах об усыновлении, заключении договоров или физической передаче животных.",
    "termsUserRespH2" to "Обязанности пользователей",
    "termsForRescuersH3" to "Для спасателей:",
    "termsRescuerResp1" to "Предоставлять точную, достоверную информацию о питомцах, находящихся на вашем попечении",
    "termsRescuerResp2" to "Обеспечивать, чтобы питомцы были здоровы, вакцинированы и надлежащим образом осмотрены ветеринаром перед размещением объявления",
    "termsRescuerResp3" to "Проводить ответственный отбор потенциальных усыновителей",
    "termsRescuerResp4" to "Организовывать безопасную передачу питомцев в их новые дома",
    "termsRescuerResp5" to "Нести ответственность за точность всей предоставленной информации",
    "termsRescuerResp6" to "Соблюдать все местные законы и правила, касающиеся усыновления животных",
    "termsRescuerResp7" to "Никогда не использовать платформу для коммерческой продажи животных или разведения",
    "termsForAdoptersH3" to "Для усыновителей:",
    "termsAdopterResp1" to "Предоставлять точную информацию о ваших жилищных условиях и опыте общения с животными",
    "termsAdopterResp2" to "Быть готовым продемонстрировать способность обеспечить надлежащий уход",
    "termsAdopterResp3" to "Понимать, что отказ от усыновления питомца причиняет животному значительный стресс",
    "termsAdopterResp4" to "Уважать право спасателя отклонить вашу заявку на усыновление",
    "termsPetListingsH2" to "Объявления о питомцах и информация",
    "termsPetListingsText1" to "Adopt-U не проверяет, не подтверждает и не гарантирует точность информации, указанной в объявлениях о питомцах. Информация, включая, помимо прочего, породу, возраст, состояние здоровья, темперамент и данные о вакцинации, предоставляется спасателями и не проходит независимую проверку.",
    "termsPetListingsText2" to "Фотографии и описания предоставляются спасателями. Хотя мы запрещаем намеренное искажение информации, мы не можем гарантировать, что все объявления точно отражают текущее состояние животного.",
    "termsPetListingsText3" to "Пользователям рекомендуется задавать вопросы, запрашивать ветеринарные документы и знакомиться с питомцем лично перед окончательным оформлением усыновления.",
    "termsAdoptionProcessH2" to "Процесс усыновления",
    "termsAdoptionProcessIntro" to "После того как спасатель и усыновитель договорились об усыновлении:",
    "termsAdoptionStep1" to "Все договорённости, включая дату и место передачи, а также любые связанные расходы, обсуждаются напрямую между сторонами",
    "termsAdoptionStep2" to "Adopt-U не проводит и не гарантирует какие-либо платёжные операции",
    "termsAdoptionStep3" to "Платформа не предоставляет договоры об усыновлении; любые договорные отношения являются исключительной ответственностью вовлечённых сторон",
    "termsAdoptionStep4" to "Мы настоятельно рекомендуем документировать все договорённости в письменном виде",
    "termsLiabilityH2" to "Ограничение ответственности",
    "termsLiabilityIntro" to "Adopt-U не несёт ответственности за:",
    "termsLiability1" to "Любые споры, разногласия или конфликты между спасателями и усыновителями",
    "termsLiability2" to "Точность информации, указанной в объявлениях о питомцах",
    "termsLiability3" to "Здоровье, поведение или состояние любого животного до, во время или после усыновления",
    "termsLiability4" to "Любые финансовые потери, ущерб или травмы, возникшие в результате использования платформы",
    "termsLiability5" to "Результат любого усыновления, включая, помимо прочего, возврат животного, проблемы со здоровьем или несовместимость",
    "termsLiability6" to "Любые действия пользователей за пределами платформы после установления контакта",
    "termsLiabilityAck" to "Пользователи признают, что усыновление питомца — это серьёзное обязательство, и берут на себя полную ответственность за своё решение об усыновлении.",
    "termsProhibitedH2" to "Запрещённые действия",
    "termsProhibitedIntro" to "На Adopt-U строго запрещены следующие действия:",
    "termsProhibited1" to "Коммерческая продажа животных, разведение или деятельность «щенячьих фабрик»",
    "termsProhibited2" to "Размещение объявлений о питомцах, за которыми вы не осуществляете непосредственный уход",
    "termsProhibited3" to "Ложная или вводящая в заблуждение информация в объявлениях или профилях",
    "termsProhibited4" to "Домогательства, дискриминация или неуместные контакты с другими пользователями",
    "termsProhibited5" to "Использование платформы для сбора личной информации в целях, не связанных с усыновлением животных",
    "termsProhibited6" to "Любая незаконная деятельность или нарушение законов о защите животных",
    "termsAccountTerminationH2" to "Прекращение действия аккаунта",
    "termsAccountTerminationText" to "Adopt-U оставляет за собой право приостанавливать или прекращать действие аккаунтов, которые нарушают настоящие условия, участвуют в запрещённой деятельности или наносят ущерб репутации платформы. Мы также можем удалять объявления, содержащие ложную, вводящую в заблуждение или неуместную информацию.",
    "termsModificationsH2" to "Изменения условий",
    "termsModificationsText" to "Мы оставляем за собой право изменять настоящие условия в любое время. Продолжение использования платформы после внесения изменений означает согласие с изменёнными условиями. Мы будем уведомлять пользователей о существенных изменениях по электронной почте или с помощью объявлений на платформе.",
    "termsContactText" to "Если у вас есть вопросы относительно настоящих Условий использования, свяжитесь с нами по адресу admin@adopt-u.com.",
