    "termsRescuerResp2" to "सूची में डालने से पहले सुनिश्चित करें कि पालतू जानवर स्वस्थ, टीकाकृत, और उचित रूप से जाँचे गए हैं",
    "termsRescuerResp3" to "संभावित गोद लेने वालों की जिम्मेदार जाँच करें",
    "termsRescuerResp4" to "पालतू जानवरों को उनके नए घरों में सुरक्षित रूप से पहुँचाने की व्यवस्था करें",
    "termsRescuerResp5" to "प्रदान की गई सभी जानकारी की सटीकता की जिम्मेदारी स्वीकार करें",
    "termsRescuerResp6" to "पालतू जानवर को गोद लेने से संबंधित सभी स्थानीय कानूनों और विनियमों का पालन करें",
    "termsRescuerResp7" to "व्यावसायिक पालतू जानवर बिक्री या प्रजनन उद्देश्यों के लिए प्लेटफ़ॉर्म का कभी उपयोग न करें",
    "termsForAdoptersH3" to "गोद लेने वालों के लिए:",
    "termsAdopterResp1" to "अपनी रहने की स्थिति और पालतू जानवरों के साथ अनुभव के बारे में सटीक जानकारी प्रदान करें",
    "termsAdopterResp2" to "उचित देखभाल प्रदान करने की अपनी क्षमता प्रदर्शित करने के लिए तैयार रहें",
    "termsAdopterResp3" to "समझें कि किसी पालतू जानवर को गोद लेने को रद्द करने से जानवर को काफ़ी तनाव होता है",
    "termsAdopterResp4" to "आपके गोद लेने के अनुरोध को अस्वीकार करने के बचावकर्ता के अधिकार का सम्मान करें",
    "termsPetListingsH2" to "पालतू जानवरों की सूची और जानकारी",
    "termsPetListingsText1" to "Adopt-U पालतू जानवरों की सूचियों में दी गई जानकारी की सटीकता को सत्यापित, समर्थन, या गारंटी नहीं देता है। नस्ल, उम्र, स्वास्थ्य स्थिति, स्वभाव, और टीकाकरण रिकॉर्ड सहित लेकिन इन्हीं तक सीमित नहीं जानकारी बचावकर्ताओं द्वारा प्रदान की जाती है और इसे स्वतंत्र रूप से सत्यापित नहीं किया गया है।",
    "termsPetListingsText2" to "तस्वीरें और विवरण बचावकर्ताओं द्वारा प्रदान किए जाते हैं। जबकि हम जानबूझकर गलत प्रस्तुति को प्रतिबंधित करते हैं, हम यह गारंटी नहीं दे सकते कि सभी सूचियाँ जानवर की वर्तमान स्थिति को सटीक रूप से दर्शाती हैं।",
    "termsPetListingsText3" to "उपयोगकर्ताओं को किसी भी गोद लेने की व्यवस्था को अंतिम रूप देने से पहले प्रश्न पूछने, पशु चिकित्सा रिकॉर्ड का अनुरोध करने, और पालतू जानवरों से मिलने के लिए प्रोत्साहित किया जाता है।",
    "termsAdoptionProcessH2" to "गोद लेने की प्रक्रिया",
    "termsAdoptionProcessIntro" to "एक बार जब बचावकर्ता और गोद लेने वाला गोद लेने की प्रक्रिया आगे बढ़ाने पर सहमत हो जाते हैं:",
    "termsAdoptionStep1" to "स्थानांतरण की तारीख, स्थान, और किसी भी संबंधित लागत सहित सभी व्यवस्थाएँ पक्षों के बीच सीधे बातचीत से तय की जाती हैं",
    "termsAdoptionStep2" to "Adopt-U किसी भी भुगतान लेनदेन को सुविधाजनक नहीं बनाता या इसकी गारंटी नहीं देता",
    "termsAdoptionStep3" to "प्लेटफ़ॉर्म गोद लेने के अनुबंध प्रदान नहीं करता है; कोई भी संविदात्मक व्यवस्था शामिल पक्षों की एकमात्र जिम्मेदारी है",
    "termsAdoptionStep4" to "हम दृढ़ता से सलाह देते हैं कि सभी समझौतों को लिखित रूप में दर्ज करें",
    "termsLiabilityH2" to "दायित्व की सीमा",
    "termsLiabilityIntro" to "Adopt-U को निम्नलिखित के लिए जिम्मेदार नहीं ठहराया जाएगा:",
    "termsLiability1" to "बचावकर्ताओं और गोद लेने वालों के बीच कोई भी विवाद, मतभेद, या संघर्ष",
    "termsLiability2" to "पालतू जानवरों की सूचियों में दी गई जानकारी की सटीकता",
    "termsLiability3" to "गोद लेने से पहले, दौरान, या बाद में किसी भी जानवर का स्वास्थ्य, व्यवहार, या स्थिति",
    "termsLiability4" to "प्लेटफ़ॉर्म के उपयोग से उत्पन्न होने वाली कोई भी वित्तीय हानि, क्षति, या चोट",
    "termsLiability5" to "किसी भी गोद लेने का परिणाम, जिसमें वापसी, स्वास्थ्य समस्याएँ, या अनुकूलता संबंधी समस्याएँ शामिल हैं लेकिन इन्हीं तक सीमित नहीं",
    "termsLiability6" to "संपर्क स्थापित होने के बाद प्लेटफ़ॉर्म के बाहर उपयोगकर्ताओं द्वारा की गई कोई भी कार्रवाई",
    "termsLiabilityAck" to "उपयोगकर्ता स्वीकार करते हैं कि पालतू जानवर को गोद लेना एक महत्वपूर्ण प्रतिबद्धता है और वे गोद लेने के अपने निर्णय की पूरी जिम्मेदारी लेते हैं।",
    "termsProhibitedH2" to "निषिद्ध गतिविधियाँ",
    "termsProhibitedIntro" to "Adopt-U पर निम्नलिखित गतिविधियाँ सख्ती से निषिद्ध हैं:",
    "termsProhibited1" to "व्यावसायिक पालतू जानवर बिक्री, प्रजनन संचालन, या पपी मिल",
    "termsProhibited2" to "ऐसे पालतू जानवरों को सूचीबद्ध करना जिनकी आप सीधे देखभाल नहीं करते",
    "termsProhibited3" to "सूचियों या प्रोफ़ाइलों में गलत या भ्रामक जानकारी",
    "termsProhibited4" to "अन्य उपयोगकर्ताओं के साथ उत्पीड़न, भेदभाव, या अनुचित संपर्क",
    "termsProhibited5" to "पालतू जानवर को गोद लेने से असंबंधित उद्देश्यों के लिए व्यक्तिगत जानकारी एकत्र करने हेतु प्लेटफ़ॉर्म का उपयोग करना",
    "termsProhibited6" to "कोई भी अवैध गतिविधियाँ या पशु कल्याण कानूनों का उल्लंघन",
    "termsAccountTerminationH2" to "खाता समाप्ति",
    "termsAccountTerminationText" to "Adopt-U उन खातों को निलंबित या समाप्त करने का अधिकार सुरक्षित रखता है जो इन शर्तों का उल्लंघन करते हैं, निषिद्ध गतिविधियों में संलग्न होते हैं, या प्लेटफ़ॉर्म को बदनाम करते हैं। हम ऐसी सूचियों को भी हटा सकते हैं जिनमें गलत, भ्रामक, या अनुचित सामग्री हो।",
    "termsModificationsH2" to "शर्तों में संशोधन",
    "termsModificationsText" to "हम किसी भी समय इन शर्तों को संशोधित करने का अधिकार सुरक्षित रखते हैं। परिवर्तनों के बाद प्लेटफ़ॉर्म का निरंतर उपयोग संशोधित शर्तों की स्वीकृति माना जाएगा। हम महत्वपूर्ण परिवर्तनों के बारे में उपयोगकर्ताओं को ईमेल या प्लेटफ़ॉर्म घोषणाओं के माध्यम से सूचित करेंगे।",
    "termsContactText" to "यदि इन नियमों और शर्तों के बारे में आपके कोई प्रश्न हैं, तो कृपया हमसे admin@adopt-u.com पर संपर्क करें।",
