    "privacyWebauthn" to "WebAuthn/FIDO2: নিরাপদ পাসকী প্রমাণীকরণের জন্য। এতে আপনার ব্রাউজারে ক্রিপ্টোগ্রাফিক অপারেশন জড়িত।",
    "privacyThirdPartySelected" to "আমরা সাবধানে এমন সেবা প্রদানকারী নির্বাচন করেছি যারা তথ্য গোপনীয়তার প্রতি আমাদের প্রতিশ্রুতি ভাগ করে নেয়।",
    "privacyChildrensH2" to "শিশুদের গোপনীয়তা",
    "privacyChildrensText" to "Adopt-U ১৮ বছরের কম বয়সী ব্যবহারকারীদের জন্য নয়। আমরা জ্ঞাতসারে অপ্রাপ্তবয়স্কদের কাছ থেকে তথ্য সংগ্রহ করি না। যদি আপনি মনে করেন কোনো অপ্রাপ্তবয়স্ক ব্যক্তি অ্যাকাউন্ট তৈরি করেছে, তবে তা অপসারণের জন্য অনুগ্রহ করে আমাদের সাথে যোগাযোগ করুন।",
    "privacyChangesH2" to "এই নীতিতে পরিবর্তন",
    "privacyChangesText" to "আমাদের অনুশীলন বা আইনি প্রয়োজনীয়তার পরিবর্তন প্রতিফলিত করতে আমরা সময়ে সময়ে এই গোপনীয়তা নীতি আপডেট করতে পারি। উল্লেখযোগ্য পরিবর্তনের বিষয়ে আমরা ইমেইল বা প্ল্যাটফর্মে সুস্পষ্ট নোটিশের মাধ্যমে ব্যবহারকারীদের জানাব।",
    "privacyContactH2" to "আমাদের সাথে যোগাযোগ করুন",
    "privacyContactText" to "এই গোপনীয়তা নীতি সম্পর্কে আপনার কোনো প্রশ্ন বা উদ্বেগ থাকলে, অথবা আপনার তথ্য অধিকার প্রয়োগ করতে, অনুগ্রহ করে admin@adopt-u.com-এ আমাদের সাথে যোগাযোগ করুন।",
    "termsConditions" to "শর্তাবলী",
    "termsAcceptanceH2" to "শর্তাবলীর গ্রহণযোগ্যতা",
