    "termsNatureH2" to "আমাদের সেবার প্রকৃতি",
    "termsNatureText1" to "Adopt-U একটি সংযোগ প্ল্যাটফর্ম যা পোষা প্রাণী উদ্ধারকারী ও সম্ভাব্য দত্তক গ্রহণকারীদের মধ্যে যোগাযোগ সহজতর করে। আমরা কোনো পোষা প্রাণীর দোকান, দালাল, আশ্রয়কেন্দ্র বা দত্তক সংস্থা নই। আমাদের প্ল্যাটফর্মে তালিকাভুক্ত কোনো পোষা প্রাণীর আমরা মালিকানা, হেফাজত বা মধ্যস্থতা করি না।",
