    "termsProhibited4" to "অন্যান্য ব্যবহারকারীদের সাথে হয়রানি, বৈষম্য বা অনুপযুক্ত যোগাযোগ",
    "termsProhibited5" to "পোষা প্রাণী দত্তকের সাথে অসম্পর্কিত উদ্দেশ্যে ব্যক্তিগত তথ্য সংগ্রহের জন্য প্ল্যাটফর্ম ব্যবহার করা",
