    "privacyDataStoredSecurely" to "तुमचा डेटा उद्योग-मानक एन्क्रिप्शन वापरून सुरक्षितपणे साठवला जातो. अनधिकृत प्रवेश, बदल, प्रकटीकरण किंवा नाशापासून तुमच्या वैयक्तिक माहितीचे संरक्षण करण्यासाठी आम्ही योग्य तांत्रिक आणि संघटनात्मक उपाययोजना करतो.",
    "privacyDataRetention" to "तुमचे खाते सक्रिय असेपर्यंत आम्ही तुमची खाते माहिती जतन करतो. तुम्ही कधीही आमच्याशी संपर्क साधून तुमचे खाते आणि संबंधित डेटा हटवण्याची विनंती करू शकता.",
    "privacyYourRightsH2" to "तुमचे हक्क",
    "privacyRightsIntro" to "तुमच्या वैयक्तिक डेटाबाबत तुम्हाला खालील हक्क आहेत:",
    "privacyRightAccess" to "प्रवेश: आम्ही तुमच्याबद्दल ठेवलेल्या सर्व वैयक्तिक डेटाची प्रत तुम्ही मागू शकता",
    "privacyRightCorrection" to "दुरुस्ती: कोणतीही चुकीची माहिती आम्ही दुरुस्त करावी अशी विनंती तुम्ही करू शकता",
    "privacyRightDeletion" to "हटवणे: तुमचे खाते आणि संबंधित सर्व डेटा हटवण्याची विनंती तुम्ही करू शकता",
    "privacyRightPortability" to "पोर्टेबिलिटी: तुमचा डेटा सामान्यतः वापरल्या जाणाऱ्या स्वरूपात द्यावा अशी विनंती तुम्ही करू शकता",
    "privacyExerciseRights" to "यापैकी कोणताही हक्क वापरण्यासाठी, कृपया आमच्याशी admin@adopt-u.com वर संपर्क साधा.",
    "privacyCookiesH2" to "कुकीज",
    "privacyCookiesText" to "Adopt-U सत्र व्यवस्थापन आणि भाषा प्राधान्यांसह प्लॅटफॉर्मच्या कार्यक्षमतेसाठी आवश्यक असलेल्या किमान कुकीज वापरते. आम्ही जाहिरात कुकीज किंवा ट्रॅकिंग कुकीज वापरत नाही.",
    "privacyThirdPartyH2" to "तृतीय-पक्ष सेवा",
    "privacyThirdPartyIntro" to "आम्ही खालील तृतीय-पक्ष सेवा वापरतो, ज्या तुमचा डेटा प्रक्रिया करू शकतात:",
    "privacyAws" to "AWS (Amazon Web Services): डेटा साठवण आणि ईमेल वितरणासाठी. तुमच्या डेटाच्या प्रक्रियेसाठी त्यांचे गोपनीयता धोरण लागू होते.",
    "privacyWebauthn" to "WebAuthn/FIDO2: सुरक्षित पासकी प्रमाणीकरणासाठी. यात तुमच्या ब्राउझरमध्ये क्रिप्टोग्राफिक प्रक्रिया समाविष्ट असतात.",
    "privacyThirdPartySelected" to "आम्ही डेटा गोपनीयतेप्रती आमची बांधिलकी सामायिक करणारे सेवा पुरवठादार काळजीपूर्वक निवडले आहेत.",
    "privacyChildrensH2" to "मुलांची गोपनीयता",
    "privacyChildrensText" to "Adopt-U १८ वर्षांखालील वापरकर्त्यांसाठी नाही. आम्ही जाणूनबुजून अल्पवयीन मुलांकडून माहिती संकलित करत नाही. एखाद्या अल्पवयीन व्यक्तीने खाते तयार केले आहे असे तुम्हाला वाटत असल्यास, ते काढून टाकण्यासाठी कृपया आमच्याशी संपर्क साधा.",
    "privacyChangesH2" to "या धोरणातील बदल",
    "privacyChangesText" to "आमच्या पद्धती किंवा कायदेशीर आवश्यकतांमधील बदल प्रतिबिंबित करण्यासाठी आम्ही वेळोवेळी हे गोपनीयता धोरण अद्यतनित करू शकतो. महत्त्वाच्या बदलांबद्दल आम्ही वापरकर्त्यांना ईमेलद्वारे किंवा प्लॅटफॉर्मवरील ठळक सूचनेद्वारे कळवू.",
    "privacyContactH2" to "आमच्याशी संपर्क साधा",
    "privacyContactText" to "या गोपनीयता धोरणाबद्दल तुम्हाला काही प्रश्न किंवा चिंता असल्यास, किंवा तुमचे डेटा हक्क वापरण्यासाठी, कृपया आमच्याशी admin@adopt-u.com वर संपर्क साधा.",
    "termsConditions" to "अटी आणि शर्ती",
    "termsAcceptanceH2" to "अटींची स्वीकृती",
    "termsAcceptanceText" to "Adopt-U मध्ये प्रवेश करून आणि वापरून, तुम्ही या कराराच्या अटी व तरतुदींनी बांधील राहण्यास स्वीकृती देता आणि सहमती दर्शवता. तुम्ही या अटींशी सहमत नसल्यास, कृपया आमचे प्लॅटफॉर्म वापरू नका.",
    "termsNatureH2" to "आमच्या सेवेचे स्वरूप",
    "termsNatureText1" to "Adopt-U हे एक जोडणी प्लॅटफॉर्म आहे जे पाळीव प्राणी बचावकर्ते आणि संभाव्य दत्तक घेणारे यांच्यातील संपर्क सुलभ करते. आम्ही पाळीव प्राण्यांचे दुकान, दलाल, आश्रयस्थान किंवा दत्तक संस्था नाही. आमच्या प्लॅटफॉर्मवर सूचीबद्ध केलेल्या कोणत्याही पाळीव प्राण्यांची मालकी, ताबा किंवा मध्यस्थ हाताळणी आमच्याकडे नसते.",
    "termsNatureText2" to "आमची भूमिका केवळ पक्षांमध्ये संवाद माध्यम पुरवण्यापुरती मर्यादित आहे. आम्ही दत्तक वाटाघाटी, करार किंवा प्राण्यांच्या भौतिक हस्तांतरणात सहभागी होत नाही.",
    "termsUserRespH2" to "वापरकर्त्याच्या जबाबदाऱ्या",
    "termsForRescuersH3" to "बचावकर्त्यांसाठी:",
    "termsRescuerResp1" to "तुमच्या काळजीतील पाळीव प्राण्यांबद्दल अचूक, सत्य माहिती द्या",
    "termsRescuerResp2" to "सूचीबद्ध करण्यापूर्वी पाळीव प्राणी निरोगी, लसीकरण केलेले आणि योग्यरित्या तपासलेले असल्याची खात्री करा",
    "termsRescuerResp3" to "संभाव्य दत्तक घेणाऱ्यांची जबाबदार पडताळणी करा",
    "termsRescuerResp4" to "पाळीव प्राण्यांचे त्यांच्या नवीन घरी सुरक्षित हस्तांतरण व्यवस्थापित करा",
    "termsRescuerResp5" to "दिलेल्या सर्व माहितीच्या अचूकतेची जबाबदारी स्वीकारा",
    "termsRescuerResp6" to "पाळीव प्राणी दत्तक घेण्याबाबत सर्व स्थानिक कायदे आणि नियमांचे पालन करा",
    "termsRescuerResp7" to "व्यावसायिक पाळीव प्राणी विक्री किंवा प्रजननाच्या उद्देशांसाठी प्लॅटफॉर्मचा कधीही वापर करू नका",
    "termsForAdoptersH3" to "दत्तक घेणाऱ्यांसाठी:",
    "termsAdopterResp1" to "तुमची राहण्याची परिस्थिती आणि पाळीव प्राण्यांबद्दलचा अनुभव याबद्दल अचूक माहिती द्या",
    "termsAdopterResp2" to "योग्य काळजी देण्याची तुमची क्षमता दाखवण्यास तयार रहा",
    "termsAdopterResp3" to "पाळीव प्राण्याचे दत्तक रद्द केल्याने प्राण्याला मोठा त्रास होतो हे समजून घ्या",
    "termsAdopterResp4" to "तुमची दत्तक विनंती नाकारण्याचा बचावकर्त्याचा हक्क मान्य करा",
    "termsPetListingsH2" to "पाळीव प्राण्यांच्या याद्या आणि माहिती",
    "termsPetListingsText1" to "पाळीव प्राण्यांच्या याद्यांमध्ये दिलेल्या माहितीची अचूकता Adopt-U पडताळत नाही, समर्थन देत नाही किंवा त्याची हमी देत नाही. जात, वय, आरोग्य स्थिती, स्वभाव आणि लसीकरण नोंदींसह परंतु त्यापुरती मर्यादित नसलेली माहिती बचावकर्त्यांनी दिलेली आहे आणि ती स्वतंत्रपणे पडताळलेली नाही.",
    "termsPetListingsText2" to "फोटो आणि वर्णने बचावकर्त्यांनी दिलेली आहेत. आम्ही जाणूनबुजून चुकीचे सादरीकरण करण्यास मनाई करत असलो तरी, सर्व याद्या प्राण्याच्या सध्याच्या स्थितीचे अचूक प्रतिनिधित्व करतात याची आम्ही हमी देऊ शकत नाही.",
    "termsPetListingsText3" to "कोणतीही दत्तक व्यवस्था अंतिम करण्यापूर्वी वापरकर्त्यांना प्रश्न विचारण्यास, पशुवैद्यकीय नोंदी मागण्यास आणि पाळीव प्राण्यांना भेटण्यास प्रोत्साहित केले जाते.",
    "termsAdoptionProcessH2" to "दत्तक प्रक्रिया",
    "termsAdoptionProcessIntro" to "एकदा बचावकर्ता आणि दत्तक घेणारा दत्तक प्रक्रियेसह पुढे जाण्यास सहमत झाल्यावर:",
    "termsAdoptionStep1" to "हस्तांतरण तारीख, स्थान आणि कोणताही संबंधित खर्च यासह सर्व व्यवस्था पक्षांमध्ये थेट वाटाघाटी केल्या जातात",
    "termsAdoptionStep2" to "Adopt-U कोणतेही देयक व्यवहार सुलभ करत नाही किंवा त्याची हमी देत नाही",
    "termsAdoptionStep3" to "प्लॅटफॉर्म दत्तक करार पुरवत नाही; कोणतीही करारात्मक व्यवस्था संबंधित पक्षांची एकमेव जबाबदारी आहे",
    "termsAdoptionStep4" to "सर्व करार लेखी स्वरूपात नोंदवण्याची आम्ही जोरदार शिफारस करतो",
    "termsLiabilityH2" to "दायित्वाची मर्यादा",
    "termsLiabilityIntro" to "Adopt-U खालील गोष्टींसाठी जबाबदार धरले जाणार नाही:",
    "termsLiability1" to "बचावकर्ते आणि दत्तक घेणारे यांच्यातील कोणतेही वाद, मतभेद किंवा संघर्ष",
    "termsLiability2" to "पाळीव प्राण्यांच्या याद्यांमध्ये दिलेल्या माहितीची अचूकता",
    "termsLiability3" to "दत्तक घेण्यापूर्वी, दरम्यान किंवा नंतर कोणत्याही प्राण्याचे आरोग्य, वर्तन किंवा स्थिती",
    "termsLiability4" to "प्लॅटफॉर्मच्या वापरामुळे उद्भवणारे कोणतेही आर्थिक नुकसान, हानी किंवा दुखापती",
    "termsLiability5" to "परतावा, आरोग्य समस्या किंवा सुसंगतता समस्यांसह परंतु त्यापुरते मर्यादित नसलेल्या कोणत्याही दत्तक प्रक्रियेचा परिणाम",
    "termsLiability6" to "संपर्क प्रस्थापित झाल्यानंतर प्लॅटफॉर्मबाहेर वापरकर्त्यांनी केलेल्या कोणत्याही कृती",
    "termsLiabilityAck" to "पाळीव प्राणी दत्तक घेणे ही एक महत्त्वाची वचनबद्धता आहे आणि दत्तक घेण्याच्या त्यांच्या निर्णयाची संपूर्ण जबाबदारी ते स्वीकारतात हे वापरकर्ते मान्य करतात.",
    "termsProhibitedH2" to "प्रतिबंधित क्रियाकलाप",
    "termsProhibitedIntro" to "Adopt-U वर खालील क्रियाकलाप कठोरपणे प्रतिबंधित आहेत:",
    "termsProhibited1" to "व्यावसायिक पाळीव प्राणी विक्री, प्रजनन कार्ये किंवा पिल्ले उत्पादन कारखाने",
    "termsProhibited2" to "तुम्ही थेट काळजी घेत नसलेल्या पाळीव प्राण्यांची यादी करणे",
    "termsProhibited3" to "याद्या किंवा प्रोफाइलमध्ये खोटी किंवा दिशाभूल करणारी माहिती",
    "termsProhibited4" to "इतर वापरकर्त्यांशी छळ, भेदभाव किंवा अनुचित संपर्क",
    "termsProhibited5" to "पाळीव प्राणी दत्तक घेण्याशी संबंधित नसलेल्या उद्देशांसाठी वैयक्तिक माहिती संकलित करण्यासाठी प्लॅटफॉर्मचा वापर करणे",
    "termsProhibited6" to "कोणतीही बेकायदेशीर कृती किंवा प्राणी कल्याण कायद्यांचे उल्लंघन",
    "termsAccountTerminationH2" to "खाते समाप्ती",
    "termsAccountTerminationText" to "या अटींचे उल्लंघन करणारी, प्रतिबंधित क्रियाकलापांमध्ये सहभागी होणारी किंवा प्लॅटफॉर्मला बदनाम करणारी खाती स्थगित किंवा समाप्त करण्याचा अधिकार Adopt-U राखून ठेवते. आम्ही खोटी, दिशाभूल करणारी किंवा अनुचित सामग्री असलेल्या याद्याही काढून टाकू शकतो.",
    "termsModificationsH2" to "अटींमध्ये सुधारणा",
    "termsModificationsText" to "या अटी कधीही सुधारण्याचा अधिकार आम्ही राखून ठेवतो. बदलांनंतर प्लॅटफॉर्मचा सतत वापर सुधारित अटींच्या स्वीकृतीस सूचित करतो. महत्त्वाच्या बदलांबद्दल आम्ही वापरकर्त्यांना ईमेल किंवा प्लॅटफॉर्म घोषणांद्वारे कळवू.",
    "termsContactText" to "या अटी व शर्तींबद्दल तुम्हाला काही प्रश्न असल्यास, कृपया आमच्याशी admin@adopt-u.com वर संपर्क साधा.",
    "language" to "भाषा",
    "displayName" to "प्रदर्शित नाव",
    "saveProfile" to "प्रोफाइल जतन करा",
    "accountSettings" to "खाते सेटिंग्ज",
    "yourRoles" to "तुमच्या भूमिका:",
    "resources" to "संसाधने",
    "loginWithPasskey" to "पासकीने लॉगिन करा",
    "signInWithPasskey" to "पासकीने साइन इन करा",
    "resendVerificationEmail" to "पडताळणी ईमेल पुन्हा पाठवा",
    "usesFido" to "सुरक्षित पासवर्डविरहित प्रमाणीकरणासाठी FIDO2 / WebAuthn वापरते.",
