    "privacyUseNotifications" to "మీకు ముఖ్యమైన ఖాతా మరియు భద్రతా నోటిఫికేషన్‌లను పంపడం",
    "privacyOnceConnected" to "మీరు మా ప్లాట్‌ఫారమ్ ద్వారా మరొక వినియోగదారుతో అనుసంధానమైన తర్వాత, తదుపరి అన్ని సంభాషణలు నేరుగా మీ మరియు ఆ వ్యక్తి మధ్య జరుగుతాయి. మీ సంభాషణల కంటెంట్‌ను మేము పర్యవేక్షించము, నిల్వ చేయము లేదా యాక్సెస్ కలిగి ఉండము.",
