    "privacyDataStorageH2" to "డేటా నిల్వ మరియు భద్రత",
    "privacyDataStoredSecurely" to "మీ డేటా పరిశ్రమ-ప్రామాణిక ఎన్‌క్రిప్షన్‌ను ఉపయోగించి సురక్షితంగా నిల్వ చేయబడుతుంది. అనధికార యాక్సెస్, మార్పు, బహిర్గతం లేదా నాశనం నుండి మీ వ్యక్తిగత సమాచారాన్ని రక్షించడానికి మేము తగిన సాంకేతిక మరియు సంస్థాగత చర్యలను అమలు చేస్తాము.",
    "privacyDataRetention" to "మీ ఖాతా చురుకుగా ఉన్నంత కాలం మేము మీ ఖాతా సమాచారాన్ని నిలుపుకుంటాము. మమ్మల్ని సంప్రదించడం ద్వారా మీరు ఎప్పుడైనా మీ ఖాతా మరియు అనుబంధిత డేటాను తొలగించమని అభ్యర్థించవచ్చు.",
    "privacyYourRightsH2" to "మీ హక్కులు",
