    "privacyWebauthn" to "WebAuthn/FIDO2: సురక్షిత పాస్‌కీ ప్రామాణీకరణ కోసం. దీనిలో మీ బ్రౌజర్‌లో క్రిప్టోగ్రాఫిక్ కార్యకలాపాలు ఉంటాయి.",
