    "privacyChildrensH2" to "పిల్లల గోప్యత",
    "privacyChildrensText" to "Adopt-U 18 సంవత్సరాల కంటే తక్కువ వయస్సు గల వినియోగదారుల కోసం ఉద్దేశించబడలేదు. మేము తెలిసి మైనర్ల నుండి సమాచారాన్ని సేకరించము. ఒక మైనర్ ఖాతాను సృష్టించారని మీరు నమ్మితే, దయచేసి దానిని తొలగించడానికి మమ్మల్ని సంప్రదించండి.",
    "privacyChangesH2" to "ఈ విధానానికి మార్పులు",
    "privacyChangesText" to "మా పద్ధతులు లేదా చట్టపరమైన అవసరాలలో మార్పులను ప్రతిబింబించడానికి మేము ఎప్పటికప్పుడు ఈ గోప్యతా విధానాన్ని నవీకరించవచ్చు. ముఖ్యమైన మార్పుల గురించి మేము ఇమెయిల్ ద్వారా లేదా ప్లాట్‌ఫారమ్‌లో ప్రముఖమైన నోటీసు ద్వారా వినియోగదారులకు తెలియజేస్తాము.",
    "privacyContactH2" to "మమ్మల్ని సంప్రదించండి",
