    "termsConditions" to "నిబంధనలు మరియు షరతులు",
    "termsAcceptanceH2" to "నిబంధనల అంగీకారం",
    "termsAcceptanceText" to "Adopt-Uను యాక్సెస్ చేయడం మరియు ఉపయోగించడం ద్వారా, మీరు ఈ ఒప్పందం యొక్క నిబంధనలు మరియు నిబంధనలచే కట్టుబడి ఉండటానికి అంగీకరిస్తారు మరియు ఒప్పుకుంటారు. మీరు ఈ నిబంధనలతో ఏకీభవించకపోతే, దయచేసి మా ప్లాట్‌ఫారమ్‌ను ఉపయోగించవద్దు.",
    "termsNatureH2" to "మా సేవ యొక్క స్వభావం",
    "termsNatureText1" to "Adopt-U అనేది పెంపుడు జంతువుల రక్షకులు మరియు సంభావ్య దత్తత తీసుకునేవారి మధ్య సంబంధాన్ని సులభతరం చేసే ఒక అనుసంధాన ప్లాట్‌ఫారమ్. మేము పెంపుడు జంతువుల దుకాణం, బ్రోకర్, ఆశ్రయం లేదా దత్తత సంస్థ కాదు. మా ప్లాట్‌ఫారమ్‌లో జాబితా చేయబడిన ఏ పెంపుడు జంతువులనైనా మేము స్వంతం చేసుకోము, సంరక్షణలో ఉంచుకోము లేదా మధ్యవర్తిగా నిర్వహించము.",
    "termsNatureText2" to "మా పాత్ర పార్టీల మధ్య సంభాషణ మార్గాన్ని అందించడానికి మాత్రమే పరిమితం చేయబడింది. దత్తత చర్చలు, ఒప్పందాలు లేదా జంతువుల భౌతిక బదిలీలో మేము పాల్గొనము.",
    "termsUserRespH2" to "వినియోగదారు బాధ్యతలు",
    "termsForRescuersH3" to "రక్షకుల కోసం:",
