    "termsForAdoptersH3" to "దత్తత తీసుకునేవారి కోసం:",
    "termsAdopterResp1" to "మీ నివాస పరిస్థితి మరియు పెంపుడు జంతువులతో అనుభవం గురించి ఖచ్చితమైన సమాచారాన్ని అందించండి",
    "termsAdopterResp2" to "సరైన సంరక్షణ అందించే మీ సామర్థ్యాన్ని ప్రదర్శించడానికి సిద్ధంగా ఉండండి",
    "termsAdopterResp3" to "పెంపుడు జంతువు దత్తతను రద్దు చేయడం జంతువుకు గణనీయమైన ఒత్తిడిని కలిగిస్తుందని అర్థం చేసుకోండి",
    "termsAdopterResp4" to "మీ దత్తత అభ్యర్థనను తిరస్కరించే రక్షకుని హక్కును గౌరవించండి",
    "termsPetListingsH2" to "పెంపుడు జంతువుల జాబితాలు మరియు సమాచారం",
    "termsPetListingsText1" to "పెంపుడు జంతువుల జాబితాలలో అందించిన సమాచారం యొక్క ఖచ్చితత్వాన్ని Adopt-U ధృవీకరించదు, ఆమోదించదు లేదా హామీ ఇవ్వదు. జాతి, వయస్సు, ఆరోగ్య స్థితి, స్వభావం మరియు టీకా రికార్డులతో సహా కానీ వాటికే పరిమితం కాని సమాచారం రక్షకులచే అందించబడుతుంది మరియు స్వతంత్రంగా ధృవీకరించబడలేదు.",
    "termsPetListingsText2" to "ఫోటోలు మరియు వివరణలు రక్షకులచే అందించబడతాయి. ఉద్దేశపూర్వక తప్పుడు ప్రాతినిధ్యాన్ని మేము నిషేధించినప్పటికీ, అన్ని జాబితాలు జంతువు యొక్క ప్రస్తుత స్థితిని ఖచ్చితంగా ప్రాతినిధ్యం వహిస్తాయని మేము హామీ ఇవ్వలేము.",
    "termsPetListingsText3" to "ఏదైనా దత్తత ఏర్పాటును ఖరారు చేయడానికి ముందు ప్రశ్నలు అడగాలని, పశువైద్య రికార్డులను అభ్యర్థించాలని మరియు పెంపుడు జంతువులను కలవాలని వినియోగదారులను ప్రోత్సహిస్తారు.",
    "termsAdoptionProcessH2" to "దత్తత ప్రక్రియ",
    "termsAdoptionProcessIntro" to "ఒక రక్షకుడు మరియు దత్తత తీసుకునేవారు దత్తతతో ముందుకు సాగడానికి అంగీకరించిన తర్వాత:",
    "termsAdoptionStep1" to "బదిలీ తేదీ, స్థానం మరియు ఏవైనా అనుబంధిత ఖర్చులతో సహా అన్ని ఏర్పాట్లు పార్టీల మధ్య నేరుగా చర్చించబడతాయి",
    "termsAdoptionStep2" to "Adopt-U ఏ చెల్లింపు లావాదేవీలను సులభతరం చేయదు లేదా హామీ ఇవ్వదు",
    "termsAdoptionStep3" to "ప్లాట్‌ఫారమ్ దత్తత ఒప్పందాలను అందించదు; ఏవైనా ఒప్పంద ఏర్పాట్లకు సంబంధించిన పార్టీలదే పూర్తి బాధ్యత",
    "termsAdoptionStep4" to "అన్ని ఒప్పందాలను వ్రాతపూర్వకంగా నమోదు చేయమని మేము గట్టిగా సిఫార్సు చేస్తున్నాము",
    "termsLiabilityH2" to "బాధ్యతా పరిమితి",
    "termsLiabilityIntro" to "Adopt-U ఈ కింది వాటికి బాధ్యత వహించదు:",
    "termsLiability1" to "రక్షకులు మరియు దత్తత తీసుకునేవారి మధ్య ఏవైనా వివాదాలు, భేదాభిప్రాయాలు లేదా సంఘర్షణలు",
    "termsLiability2" to "పెంపుడు జంతువుల జాబితాలలో అందించిన సమాచారం యొక్క ఖచ్చితత్వం",
    "termsLiability3" to "దత్తతకు ముందు, సమయంలో లేదా తర్వాత ఏదైనా జంతువు యొక్క ఆరోగ్యం, ప్రవర్తన లేదా స్థితి",
    "termsLiability4" to "ప్లాట్‌ఫారమ్ వినియోగం నుండి ఉత్పన్నమయ్యే ఏవైనా ఆర్థిక నష్టాలు, నష్టాలు లేదా గాయాలు",
    "termsLiability5" to "రిటర్న్‌లు, ఆరోగ్య సమస్యలు లేదా అనుకూలత సమస్యలతో సహా కానీ వాటికే పరిమితం కాని ఏదైనా దత్తత ఫలితం",
    "termsLiability6" to "సంప్రదింపు ఏర్పడిన తర్వాత ప్లాట్‌ఫారమ్ వెలుపల వినియోగదారులు తీసుకున్న ఏవైనా చర్యలు",
    "termsLiabilityAck" to "పెంపుడు జంతువును దత్తత తీసుకోవడం ఒక ముఖ్యమైన నిబద్ధత అని మరియు దత్తత తీసుకోవాలనే తమ నిర్ణయానికి పూర్తి బాధ్యత తామే వహిస్తామని వినియోగదారులు అంగీకరిస్తారు.",
    "termsProhibitedH2" to "నిషేధిత కార్యకలాపాలు",
    "termsProhibitedIntro" to "Adopt-Uలో ఈ కింది కార్యకలాపాలు ఖచ్చితంగా నిషేధించబడ్డాయి:",
    "termsProhibited1" to "వాణిజ్య పెంపుడు జంతువుల అమ్మకాలు, సంతానోత్పత్తి కార్యకలాపాలు లేదా పప్పీ మిల్లులు",
    "termsProhibited2" to "మీరు నేరుగా సంరక్షించని పెంపుడు జంతువులను జాబితా చేయడం",
    "termsProhibited3" to "జాబితాలు లేదా ప్రొఫైల్‌లలో తప్పుడు లేదా తప్పుదోవ పట్టించే సమాచారం",
    "termsProhibited4" to "ఇతర వినియోగదారులతో వేధింపులు, వివక్ష లేదా అనుచిత సంప్రదింపు",
    "termsProhibited5" to "పెంపుడు జంతువుల దత్తతకు సంబంధం లేని ప్రయోజనాల కోసం వ్యక్తిగత సమాచారాన్ని సేకరించడానికి ప్లాట్‌ఫారమ్‌ను ఉపయోగించడం",
    "termsProhibited6" to "ఏవైనా చట్టవిరుద్ధ కార్యకలాపాలు లేదా జంతు సంక్షేమ చట్టాల ఉల్లంఘనలు",
    "termsAccountTerminationH2" to "ఖాతా రద్దు",
    "termsAccountTerminationText" to "ఈ నిబంధనలను ఉల్లంఘించే, నిషేధిత కార్యకలాపాలలో పాల్గొనే లేదా ప్లాట్‌ఫారమ్‌ను అప్రతిష్ఠపాలు చేసే ఖాతాలను నిలిపివేయడానికి లేదా రద్దు చేయడానికి Adopt-U హక్కును కలిగి ఉంది. తప్పుడు, తప్పుదోవ పట్టించే లేదా అనుచితమైన కంటెంట్‌ను కలిగి ఉన్న జాబితాలను కూడా మేము తొలగించవచ్చు.",
    "termsModificationsH2" to "నిబంధనలకు మార్పులు",
    "termsModificationsText" to "ఏ సమయంలోనైనా ఈ నిబంధనలను సవరించే హక్కును మేము కలిగి ఉన్నాము. మార్పుల తర్వాత ప్లాట్‌ఫారమ్‌ను కొనసాగించి ఉపయోగించడం సవరించిన నిబంధనల అంగీకారాన్ని సూచిస్తుంది. ముఖ్యమైన మార్పుల గురించి మేము ఇమెయిల్ ద్వారా లేదా ప్లాట్‌ఫారమ్ ప్రకటనల ద్వారా వినియోగదారులకు తెలియజేస్తాము.",
    "termsContactText" to "ఈ నిబంధనలు మరియు షరతుల గురించి మీకు ఏవైనా ప్రశ్నలు ఉంటే, దయచేసి admin@adopt-u.com వద్ద మమ్మల్ని సంప్రదించండి.",
    "language" to "భాష",
