@JsExport
@JsName("i18n")
object I18n {
    var currentLang: String = "en"
    private val loadedLangs = mutableSetOf<String>()

    private val translations = mapOf(
        "en" to englishTranslations,
        "es" to spanishTranslations,
        "fr" to frenchTranslations,
        "pt" to portugueseTranslations,
        "zh" to chineseTranslations,
        "ar" to arabicTranslations,
