        "te" to "\uD83C\uDDEE\uD83C\uDDF3"
    )

    fun loadLang(lang: String): Promise<Unit> {
        currentLang = lang
        return Promise.resolve(Unit)
    }

    fun t(key: String): String {
        val langTranslations = translations[currentLang] ?: englishTranslations
        val value = langTranslations[key]
        return value?.toString() ?: key
    }

